&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;What&amp;nbsp;you’ll&amp;nbsp;do as a&amp;nbsp;Platform Engineer&amp;nbsp;at Akuna:&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:276,&amp;quot;469777462&amp;quot;:[9360],&amp;quot;469777927&amp;quot;:[0],&amp;quot;469777928&amp;quot;:[4]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
